import {defaultState,validateState} from './progress-core.mjs';
import {CloudSync} from './cloud-sync.mjs';
'use strict';
const KEY='english-step-v1';
const DAY=86400000;
const iconPaths={film:'M3 3h18v18H3zM7 3v18m10-18v18M3 7h4m-4 5h4m-4 5h4m10-10h4m-4 5h4m-4 5h4',home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',book:'M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1m0-15c3-2 6-2 9-1v15c-3-1-6-1-9 1Zm0 0v15',repeat:'M20 7a8 8 0 0 0-14-2L3 8m0-5v5h5m-4 9a8 8 0 0 0 14 2l3-3m0 5v-5h-5',words:'M4 4h9v16H4zm9 0h7v16h-7M7 8h3m-3 4h3m6-4h1m-1 4h1',chart:'M4 20V10m8 10V4m8 16v-7M2 21h20',arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',fire:'M12 3c2 5 7 6 7 12a7 7 0 0 1-14 0c0-3 2-6 4-7 0 3 1 4 2 4 2-2 2-5 1-9Z',check:'m5 12 4 4L19 6',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-2.9-5.6 2.9 1.1-6.2L3 9.6l6.2-.9Z',sound:'M11 4 6 8H3v8h3l5 4Zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3l-.7 2.5L6 7l-2.5-.5-1 3L4 12l-1.5 2.5 1 3L6 17l2.3 1.5L9 21h6l.7-2.5L18 17l2.5.5 1-3L20 12l1.5-2.5-1-3L18 7l-2.3-1.5L15 3Z',bulb:'M9 18h6m-5 3h4M8 14a6 6 0 1 1 8 0c-1 1-1 2-1 2H9s0-1-1-2',close:'m6 6 12 12M6 18 18 6',calendar:'M4 5h16v16H4zm3-3v6m10-6v6M4 10h16',leaf:'M20 3C7 2 2 8 6 15s15 1 14-12ZM6 20 17 7',target:'M21 12a9 9 0 1 1-9-9m0 4a5 5 0 1 0 5 5M12 12l9-9m-5 0h5v5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',info:'M12 11v6m0-10v.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',play:'m8 4 12 8-12 8Z'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.book}"/></svg>`}
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function today(offset=0){const d=new Date();d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
let storageOK=true;
function loadState(){try{const raw=localStorage.getItem(KEY);return raw?validateState(JSON.parse(raw)):defaultState()}catch(err){storageOK=false;return defaultState()}}
let state=loadState(),units=[],mediaLessons=[],filmCatalog={levels:[],films:[],sources:[]},allQuestions=[],words=[],session=null,lesson=null,lessonTab='learn',showTranslation=true,route='',filter='all',query='';
const app=document.getElementById('app'),dialog=document.getElementById('lessonDialog'),content=document.getElementById('lessonContent');
const cloud=new CloudSync({getState:()=>state,setState:v=>state=v,onStatus:updateSyncStatus,onRemote:()=>{if(route&&route!=='settings')shell()},onNotice:message=>toast(message)});
let autoSaveTimer;
function save(){const ok=cloud.save();if(!ok)storageOK=false;clearTimeout(autoSaveTimer);autoSaveTimer=setTimeout(()=>cloud.sync(),400);return ok}
function updateSyncStatus(){const labels={connecting:'Подключение…',pending:'Ждёт сохранения',saving:'Сохраняем…',saved:'Сохранено в аккаунте',offline:'Нет связи · на устройстве',auth:'Нужен вход'};for(const el of document.querySelectorAll('[data-sync-status]')){el.textContent=labels[cloud.status]||'Подключение…';el.dataset.status=cloud.status}const detail=document.getElementById('cloudDetail');if(detail)detail.textContent=cloud.user?`Аккаунт: ${cloud.user.email}. ${cloud.lastSaved?'Последнее сохранение: '+new Date(cloud.lastSaved).toLocaleString('ru-RU'):''}`:'Подключаем твой аккаунт…'}
function cloudBadge(){return `<a class="sync-badge" data-sync-status data-status="${cloud.status}" href="#settings">${({saved:'Сохранено в аккаунте',offline:'Нет связи · на устройстве',auth:'Нужен вход',saving:'Сохраняем…',pending:'Ждёт сохранения'})[cloud.status]||'Подключение…'}</a>`}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4000)}
function dayStats(){return state.days[today()]||{answers:0,correct:0,lessons:0,spoken:0}}
function streak(){let count=0,offset=dayStats().answers>0?0:-1;for(let i=offset;i>offset-366;i--){if((state.days[today(i)]?.answers||0)>0)count++;else break}return count}
function completion(){return trackCount()}
function dueQuestions(){return allQuestions.filter(q=>state.items[q.key]&&state.items[q.key].due<=Date.now()).sort((a,b)=>state.items[a.key].due-state.items[b.key].due)}
function errorQuestions(){return allQuestions.filter(q=>state.items[q.key]?.lastWrong)}
function nextUnit(){const list=trackUnits();return list.find(u=>u.id>=state.recommended&&!state.units[u.id]?.completed)||list.find(u=>!state.units[u.id]?.completed)||list[0]}
function shuffle(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function normal(s){return String(s).normalize('NFKC').toLowerCase().replace(/[’‘`]/g,"'").replace(/[.,!?;:"“”]/g,'').replace(/\s+/g,' ').trim()}
function correctAnswer(q,value){return (q.answers||[q.answer]).some(a=>normal(a)===normal(value))}
function recordAnswer(q,ok,assisted){
 const d=state.days[today()]||{answers:0,correct:0,lessons:0,spoken:0};d.answers++;if(ok&&!assisted)d.correct++;state.days[today()]=d;state.xp+=ok&&!assisted?10:2;
 if(q.key.startsWith('u')&&q.key.includes('-q')){const prev=state.items[q.key],now=Date.now(),intervals=[1,3,7,14,30],success=ok&&!assisted;const stage=success?(prev&&!prev.lastWrong?(prev.due<=now?Math.min(4,prev.stage+1):prev.stage):0):0;const due=success?(prev&&!prev.lastWrong&&prev.due>now?prev.due:now+intervals[stage]*DAY):now+10*60000;state.items[q.key]={due,stage,attempts:(prev?.attempts||0)+1,correct:(prev?.correct||0)+(success?1:0),lastWrong:!success,updatedAt:now}}
 save();
}
const navItems=[['home','home','Сегодня'],['course','book','Мой курс'],['review','repeat','Повторение'],['words','words','Словарь'],['films','film','Кино'],['progress','chart','Прогресс']];
const routeTitles={home:'Сегодня',course:'Мой курс',review:'Повторение',words:'Словарь',films:'Кино на английском',progress:'Мой прогресс',method:'Как это работает',settings:'Настройки'};
const tracks=[{id:'grammarway',name:'Grammarway 1',level:'A1–A2',publisher:'Базовый курс',tagline:'Создаём грамматический фундамент',description:'20 уроков с понятными правилами и практикой.'},{id:'english-file',name:'English File · Intermediate',level:'B1–B1+',publisher:'Oxford University Press · 5th Edition',tagline:'Говорим увереннее каждый день',description:'20 уроков 1A–10B: грамматика, темы общения, произношение и диалоги.'},{id:'dk',name:'English for Everyone · Advanced',level:'B2–C1',publisher:'DK · Level 4',tagline:'Расширяем выразительность речи',description:'69 небольших модулей: сложные конструкции, точные формулировки и лексика.'}];
const chapterNames={grammarway:['Первые фразы','Повседневная жизнь','Истории и планы','Больше выразительности'], 'english-file':['Еда и семья','Деньги и перемены','Сравнения и стереотипы','Правила и возможности','Спорт и отношения','Кино и наблюдения','Образование и дом','Работа и общение','Возможности и техника','Люди и тайны'],dk:['Общение и описания','Путешествия и советы','Связность и сравнения','Учёба и идеи','Работа и карьера','Встречи и точность','Экология и условия','Гипотезы и выводы','Медиа и акценты','Закон и модальность','Культура и обобщения','Технологии и будущее','Искусство и стиль','Выразительность речи']};
function activeTrack(){return tracks.find(x=>x.id===state.settings.track)?.id||'grammarway'}
function trackInfo(id=activeTrack()){return tracks.find(x=>x.id===id)||tracks[0]}
function trackUnits(id=activeTrack()){return units.filter(u=>(u.track||'grammarway')===id)}
function trackCount(id=activeTrack()){return trackUnits(id).filter(u=>state.units[u.id]?.completed).length}
function trackSwitcher(){return `<section class="track-switcher" aria-label="Выбери ступень обучения">${tracks.map((t,i)=>{const n=trackUnits(t.id).length;const done=trackCount(t.id);return `<button type="button" class="track-tile ${t.id===activeTrack()?'selected':''}" aria-pressed="${t.id===activeTrack()}" data-action="track" data-id="${t.id}"><span class="track-step">СТУПЕНЬ ${i+1} · ${t.level}</span><strong>${e(t.name)}</strong><span>${e(t.description)}</span><span class="track-stats">${done} из ${n} освоено <span aria-hidden="true">↗</span></span><span class="track-line"><i style="width:${n?done/n*100:0}%"></i></span></button>`}).join('')}</section>`}
function trackProgressStrip(){return `<div class="track-progress-strip">${tracks.map(t=>`<button data-action="track-go" data-id="${t.id}"><strong>${e(t.level)}</strong><small>${trackCount(t.id)} из ${trackUnits(t.id).length} освоено</small><span class="track-line"><i style="width:${trackUnits(t.id).length?trackCount(t.id)/trackUnits(t.id).length*100:0}%"></i></span></button>`).join('')}</div>`}
function shell(){
 const due=dueQuestions().length,c=completion();
 app.innerHTML=`<aside class="sidebar"><a class="brand" href="#home"><img src="icon.svg" alt=""><span><strong>English Step</strong><small>Маленькие шаги. Большие перемены.</small></span></a><div class="nav-label">ТВОЁ ОБУЧЕНИЕ</div><nav class="nav" aria-label="Основная навигация">${navItems.map(([id,ic,label])=>`<a href="#${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='review'&&due?`<span class="badge">${due}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="course-mini"><strong>${e(trackInfo().name)}</strong><div style="display:flex;justify-content:space-between;font-size:10px;color:#849376;margin:10px 0"><span>${e(trackInfo().level)}</span><span>${c}/${trackUnits().length}</span></div><div class="progress"><i style="width:${trackUnits().length?c/trackUnits().length*100:0}%"></i></div><p>Понимай. Пробуй. Повторяй.</p></div><nav class="nav" aria-label="Помощь"><a href="#method" class="${route==='method'?'active':''}">${icon('bulb')}Как учиться</a><a href="#settings" class="${route==='settings'?'active':''}">${icon('settings')}Настройки</a></nav><div class="user"><div class="avatar">${e(state.name.slice(0,1).toUpperCase())}</div><div><strong>${e(state.name)}</strong><small>${state.xp>=1000?'Уверенные шаги':state.xp>=300?'Исследователь':'Начало пути'} · ${state.xp} XP</small></div></div></div></aside><div class="layout"><header class="topbar"><div class="breadcrumbs">Личный кабинет ${icon('chevron')} <strong>${routeTitles[route]}</strong></div><a href="#home" class="mobile-brand" style="text-decoration:none;color:inherit"><img src="icon.svg" alt="">English Step</a><div class="top-actions">${cloudBadge()}<span class="streak">${icon('fire')} ${streak()} ${plural(streak(),'день','дня','дней')} подряд</span><span class="pill">${e(trackInfo().level)}</span><a href="#settings" class="avatar" aria-label="Настройки профиля" style="text-decoration:none">${e(state.name.slice(0,1).toUpperCase())}</a></div></header>${!storageOK?'<div class="error-banner">Сохранение браузера недоступно или сохранённые данные повреждены. Экспортируй прогресс в настройках перед закрытием.</div>':''}<main class="main" id="main" tabindex="-1"></main></div>`;
 renderPage();updateSyncStatus();
}
function plural(n,a,b,c){return n%10===1&&n%100!==11?a:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?b:c}
function heading(title,sub,extra=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`}
function footer(){return `<footer class="footer"><span>English Step · Grammarway 1 · Oxford English File · DK Advanced</span><button data-action="navigate" data-route="method">Методика и источники ↗</button></footer>`}
function renderPage(){const m=document.getElementById('main');const views={home:homeView,course:courseView,review:reviewView,words:wordsView,films:filmsView,progress:progressView,method:methodView,settings:settingsView};m.innerHTML=views[route]()+footer();document.title=`${routeTitles[route]} — English Step`}
function heroArt(){return `<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 260 270" fill="none"><circle cx="140" cy="157" r="105" stroke="#42685c" stroke-dasharray="3 6"/><circle cx="165" cy="139" r="73" fill="#315d50"/><path d="M62 195h114v24H62z" fill="#91aa78"/><path d="M62 195h6v24h-6z" fill="#6c8b63"/><path d="M78 168h127v24H78z" fill="#e6eabd"/><path d="M82 172h117m-117 6h117m-117 6h117" stroke="#c5ce9f"/><path d="M51 217h154v24H51z" fill="#d4a17c"/><path d="M58 220v18" stroke="#b78866" stroke-width="2"/><rect x="89" y="58" width="96" height="111" rx="8" transform="rotate(12 89 58)" fill="#f0f0d7"/><path d="m100 65-20 99" stroke="#d9dfbd" stroke-width="3"/><path d="m118 99 8-13 8 17m-12-9 10 2m9 14 8-15 2 17m-5-8 6 1" stroke="#385d4c" stroke-width="3" stroke-linecap="round"/><path d="m103 124 47 10m-50 4 34 7" stroke="#b9c7a0" stroke-width="3" stroke-linecap="round"/><rect x="173" y="86" width="48" height="36" rx="9" transform="rotate(-12 173 86)" fill="#dce9a6"/><path d="m187 99 5 4 11-13" stroke="#526c46" stroke-width="2.5" stroke-linecap="round"/><path d="m58 81 3 7 8 2-8 3-3 7-3-7-8-3 8-2Z" fill="#b7cc8c"/><circle cx="207" cy="154" r="3" fill="#bdd190"/><path d="m202 51 1 4 4 1-4 1-1 4-1-4-4-1 4-1Z" fill="#bdd190"/><path d="M212 216c-15-34 11-44 3-64 20 13 14 33-3 64Z" fill="#88a675"/><path d="M212 216c-8-18-27-13-30-35 17 0 30 14 30 35Z" fill="#627f59"/><path d="M201 219h25l-4 22h-17Z" fill="#e5e5c9"/></svg></div>`}
function homeView(){const u=nextUnit(),d=dayStats(),done=completion(),due=dueQuestions().length;const studied=Object.keys(state.items).length;const correct=Object.values(state.days).reduce((a,v)=>a+v.correct,0),attempts=Object.values(state.days).reduce((a,v)=>a+v.answers,0);const list=trackUnits();const idx=list.findIndex(x=>x.id===u.id);let start=Math.floor(Math.max(0,idx)/5)*5;const routeUnits=list.slice(start,start+5);const info=trackInfo();return heading(`Привет, ${e(state.name)} <span style="font-weight:400">✦</span>`,'Три ступени английского. Выбери свою — занимайся в комфортном темпе.',`<div class="date-chip">${icon('calendar')}${new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</div>`)+trackProgressStrip()+`<div class="dashboard-grid"><div><section class="hero"><div class="hero-content"><div class="eyebrow">${e(info.level)} · ${e(info.name)} · УРОК ${e(u.unitNo||String(u.id).padStart(2,'0'))}</div><h2>${done===list.length?'Закрепим то, что умеешь?':idx===0&&done===0?'Большой путь.<br>Начнём с малого.':e(u.ru)}</h2><p>${e(u.summary)} Разбирай, закрепляй, применяй в речи.</p><button class="btn lime" data-action="lesson" data-id="${u.id}">${state.units[u.id]?'Продолжить учиться':'Начать урок'} ${icon('arrow')}</button><span class="hero-caption">${icon('clock')} ≈ ${u.minutes||12} минут</span></div>${heroArt()}</section><div class="stats"><div class="stat"><div class="iconbox">${icon('book')}</div><div><strong>${done}<span style="font-size:12px;color:#a5ad9e;font-weight:500"> / ${list.length}</span></strong><small>уроков освоено</small></div></div><div class="stat"><div class="iconbox peach">${icon('target')}</div><div><strong>${attempts?Math.round(correct/attempts*100)+'%':'—'}</strong><small>точность ответов</small></div></div><div class="stat"><div class="iconbox blue">${icon('repeat')}</div><div><strong>${due}</strong><small>заданий на повтор</small></div></div></div><div class="section-title"><h2>Твой маршрут · ${e(info.level)}</h2><a class="text-btn" href="#course">Все уроки ${icon('arrow')}</a></div><section class="route" aria-label="Ближайшие уроки">${routeUnits.map(x=>`<button class="route-row ${state.units[x.id]?.completed?'done':x.id===u.id?'current':''}" data-action="lesson" data-id="${x.id}"><span class="route-num">${state.units[x.id]?.completed?icon('check'):e(x.unitNo||String(x.id).padStart(2,'0'))}</span><span class="route-text"><strong>${e(x.title)}</strong><small>${e(x.ru)}</small></span><span class="route-meta">${state.units[x.id]?.completed?'Освоено':x.id===u.id?'Начнём здесь':`${x.minutes||12} мин`}</span>${icon('chevron')}</button>`).join('')}</section><div class="route-footer"><span>Глава ${Math.floor(start/5)+1} · ${e(chapterNames[activeTrack()][u.chapter-1]||'Продолжение')}</span><span>В своём темпе</span></div><div class="callout">${icon('bulb')}<p><strong>Уже знаком с этой ступенью?</strong>Пройди небольшую диагностику по её темам и начни там, где полезнее.</p><button class="text-btn" data-action="diagnostic">Попробовать ${icon('arrow')}</button></div></div><aside class="dashboard-side"><section class="card daily-card"><div class="card-head"><h2>План на сегодня</h2><small>≈ 15 минут</small></div><div class="goal-ring" style="--percent:${Math.min(100,d.answers/state.goal*100)}"><div><strong>${d.answers}<span style="font-size:14px;color:#a1ae91;font-weight:400">/${state.goal}</span></strong><small>ответов за день</small></div></div><div class="checklist"><button data-action="lesson" data-id="${u.id}"><span class="check ${d.lessons?'checked':''}">${d.lessons?'✓':'1'}</span><span><strong>Разобраться в новом</strong><small>Один короткий урок</small></span></button><button data-action="daily"><span class="check ${d.answers>=state.goal?'checked':''}">${d.answers>=state.goal?'✓':'2'}</span><span><strong>Вспомнить и закрепить</strong><small>Ежедневная практика</small></span></button><button data-action="speak-unit" data-id="${u.id}"><span class="check ${d.spoken?'checked':''}">${d.spoken?'✓':'3'}</span><span><strong>Сказать вслух</strong><small>Две фразы о себе</small></span></button></div><button class="btn full white" data-action="daily">${d.answers>=state.goal?'Ещё немного практики':'Тренировка дня'} ${icon('arrow')}</button></section><section class="phrase-card"><div class="eyebrow">МАЛЕНЬКАЯ ФРАЗА ДНЯ</div><h3>One step<br>at a time.</h3><p>Шаг за шагом.<br>Всё получится.</p><button class="audio-btn" data-action="phrase">${icon('sound')} Послушать</button><div style="border-top:1px solid #dfe4d2;margin-top:24px;padding-top:16px;font-size:10px;color:#929d81;line-height:1.8">Произнеси фразу вслух.<br>Потом попробуй по памяти.</div></section><div class="tip">${icon('leaf')}<span>15 минут — удобный старт. Главное — регулярно возвращаться.</span></div></aside></div>`}
function courseView(){const info=trackInfo();return heading('Твой курс английского','Выбирай ступень: базовая грамматика, уверенное общение или продвинутые конструкции.')+trackSwitcher()+`<div class="course-track-head"><span class="course-track-level">${e(info.level)}</span><div><h2>${e(info.name)}</h2><p>${e(info.publisher)} · ${e(info.tagline)}</p></div></div><div class="filterbar"><button class="filter ${filter==='all'?'active':''}" data-action="course-filter" data-filter="all">Все уроки</button><button class="filter ${filter==='new'?'active':''}" data-action="course-filter" data-filter="new">Не освоены</button><button class="filter ${filter==='done'?'active':''}" data-action="course-filter" data-filter="done">Освоены · ${completion()}</button><input class="search" id="courseSearch" placeholder="Найти тему…" aria-label="Поиск урока" value="${e(query)}"></div><div id="courseResults">${courseResults()}</div>`}
function courseResults(){const current=trackUnits();const matches=current.filter(u=>(filter==='all'||(filter==='done'?state.units[u.id]?.completed:!state.units[u.id]?.completed))&&`${u.title} ${u.ru} ${u.summary}`.toLowerCase().includes(query.toLowerCase()));if(!matches.length)return '<div class="empty"><h2>Пока ничего не найдено</h2><p>Попробуй другой запрос или выбери все уроки.</p></div>';const info=trackInfo();return [...new Set(matches.map(u=>u.chapter))].map(chapter=>{const list=matches.filter(u=>u.chapter===chapter);const chapterAll=current.filter(u=>u.chapter===chapter);return `<section class="chapter"><div class="chapter-title"><span>${chapter}</span><div><h2>${e(chapterNames[activeTrack()][chapter-1]||'Продолжение')}</h2><p>${list.length} ${plural(list.length,'урок','урока','уроков')} · ${e(info.level)}</p></div></div><div class="lesson-grid">${list.map(u=>`<button class="lesson-card" data-action="lesson" data-id="${u.id}"><span class="lesson-number">${e(u.unitNo||`УРОК ${String(u.id).padStart(2,'0')}`)} ${state.units[u.id]?.completed?'<span class="pill">✓ Освоено</span>':''}</span><h3>${e(u.title)}</h3><p>${e(u.ru)}<br>${e(u.summary)}</p><span class="bottom"><span>${u.exercises.length} заданий · ≈ ${u.minutes||12} мин</span>${icon('arrow')}</span></button>`).join('')}</div><div class="revision"><div><strong>Вспомнить тему · ${e(info.name)}</strong><p>Смешанная проверка после главы. Можно выполнять сколько угодно раз.</p></div><button class="btn white" data-action="track-revision" data-id="${chapter}">Повторить главу ${icon('arrow')}</button></div></section>`}).join('')}
function reviewView(){const due=dueQuestions(),errors=errorQuestions(),known=Object.keys(state.items).length;return heading('Вспомнить — значит закрепить','Сначала попробуй ответить по памяти. Объяснение появится после ответа.')+`<section class="review-hero"><div><h2>${due.length?'Пора освежить знания':known?'Сегодня всё повторено':'Твоя память любит возвращаться'}</h2><p>${due.length?'Задания возвращаются через интервалы: 1, 3, 7, 14 и 30 дней.':known?'Следующие задания появятся, когда придёт время. Можно потренировать ошибки.':'Пройди первый урок — и здесь появится твой план повторений.'}</p><button class="btn" data-action="${due.length?'review-due':known?'daily':'lesson'}" data-id="1">${due.length?'Начать повторение':known?'Смешанная практика':'Начать первый урок'} ${icon('arrow')}</button></div><div class="big">${due.length}</div></section><div class="two-col"><section class="card"><div class="card-head"><h2>Мои ошибки</h2><span class="pill">${errors.length}</span></div><p class="muted" style="font-size:12px">Ошибаться нормально. Разберём трудные места и попробуем ещё раз.</p>${errors.length?`<div class="review-list">${errors.slice(0,5).map(q=>`<div class="review-item"><div><strong>${e(q.unitTitle)}</strong><small>${e(q.prompt.slice(0,95))}</small></div>${icon('repeat')}</div>`).join('')}</div><button class="btn white full" style="margin-top:20px" data-action="review-errors">Поработать над ошибками</button>`:'<div class="notice">Здесь пока пусто. Задания с ошибками будут собираться автоматически.</div>'}</section><section class="card"><div class="card-head"><h2>Ближайшие повторения</h2>${icon('calendar')}</div>${known?nextReviews():'<p class="muted" style="font-size:12px">После первого ответа мы начнём составлять расписание. Оно меняется в зависимости от твоих результатов.</p>'}<div class="notice" style="font-size:11px">После ошибки задание вернётся через 10 минут. В разделе «Мои ошибки» его можно повторить сразу.</div></section></div>`}
function nextReviews(){const rows=[];for(let i=0;i<7;i++){const dt=new Date();dt.setHours(0,0,0,0);dt.setDate(dt.getDate()+i);const start=dt.getTime(),end=start+DAY;const n=allQuestions.filter(q=>state.items[q.key]&&state.items[q.key].due<end&&(i===0||state.items[q.key].due>=start)).length;rows.push(`<div class="review-item"><div>${i===0?'Сегодня':i===1?'Завтра':dt.toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</div><strong>${n}</strong></div>`)}return rows.join('')}
function wordsView(){return heading('Слова, которые пригодятся',`${words.length} выражений из трёх ступеней. Открой словарь своей ступени и закрепляй лексику.`)+`<div class="filterbar"><button class="filter ${filter!=='starred'?'active':''}" data-action="word-filter" data-filter="all">Все слова · ${trackUnits().reduce((a,u)=>a+u.vocab.length,0)}</button><button class="filter ${filter==='starred'?'active':''}" data-action="word-filter" data-filter="starred">Избранное · ${words.filter(w=>(units.find(u=>u.id===w.unitId)?.track||'grammarway')===activeTrack()&&state.stars.includes(w.key)).length}</button><button class="btn white" data-action="word-practice">${icon('repeat')} Тренировать слова</button><input class="search" id="wordSearch" placeholder="Слово или перевод…" aria-label="Поиск слова" value="${e(query)}"></div><div class="word-list" id="wordResults">${wordResults()}</div>`}
function filteredWords(){return words.filter(w=>(units.find(u=>u.id===w.unitId)?.track||'grammarway')===activeTrack()&&(filter!=='starred'||state.stars.includes(w.key))&&`${w.en} ${w.ru}`.toLowerCase().includes(query.toLowerCase()))}
function wordResults(){const list=filteredWords();return list.length?list.map(w=>`<div class="word-row"><button class="icon-btn" data-action="speak-word" data-id="${w.key}" aria-label="Послушать ${e(w.en)}">${icon('sound')}</button><div class="word-text"><strong>${e(w.en)}</strong><span>${e(w.ru)}</span><p>${e(w.example)}</p></div><span class="word-unit">${e(units.find(u=>u.id===w.unitId)?.unitNo||`Урок ${w.unitId}`)}</span><button class="icon-btn ${state.stars.includes(w.key)?'active':''}" aria-pressed="${state.stars.includes(w.key)}" data-action="star" data-id="${w.key}" aria-label="${state.stars.includes(w.key)?'Убрать из':'Добавить в'} избранное: ${e(w.en)}">${icon('star')}</button></div>`).join(''):'<div class="search-empty">Здесь пока нет слов. Попробуй другой запрос или добавь слова в избранное.</div>'}
function progressView(){const data=Object.values(state.days),answers=data.reduce((a,v)=>a+v.answers,0),correct=data.reduce((a,v)=>a+v.correct,0),week=Array.from({length:7},(_,i)=>({date:today(i-6),n:state.days[today(i-6)]?.answers||0})),max=Math.max(state.goal,...week.map(d=>d.n));return heading('Твой прогресс','Каждый ответ — маленький вклад в большой результат.')+trackProgressStrip()+`<div class="metric-grid"><div class="card"><strong>${completion()}<span style="font-size:15px;color:#a6b095">/${trackUnits().length}</span></strong><p>уроков освоено</p></div><div class="card"><strong>${answers}</strong><p>выполнено заданий</p></div><div class="card"><strong>${answers?Math.round(correct/answers*100)+'%':'—'}</strong><p>ответов без подсказки</p></div><div class="card"><strong>${streak()}</strong><p>${plural(streak(),'день','дня','дней')} подряд</p></div></div><div class="two-col"><section class="card"><div class="card-head"><h2>Твоя неделя</h2><span class="muted" style="font-size:10px">Число ответов</span></div><div class="activity-chart" role="img" aria-label="Ответы за неделю: ${week.map(d=>d.date+': '+d.n).join(', ')}">${week.map((d,i)=>`<div class="activity-day ${i===6?'today':''}"><span>${d.n}</span><div class="bar" style="height:${d.n/max*95}px"></div><span>${new Date(d.date+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'short'})}</span></div>`).join('')}</div></section><section class="card"><div class="card-head"><h2>Навыки в практике</h2>${icon('target')}</div>${[['choice','Узнать верную форму'],['input','Вспомнить без вариантов'],['order','Построить предложение'],['listen','Услышать и записать']].map(([type,title])=>{let a=0,c=0;allQuestions.filter(q=>q.type===type).forEach(q=>{a+=state.items[q.key]?.attempts||0;c+=state.items[q.key]?.correct||0});const val=a?Math.round(c/a*100):0;return `<div class="accuracy-row"><div><span>${title}</span><span>${a?val+'%':'Ещё не пробовали'}</span></div><div class="progress"><i style="width:${val}%"></i></div></div>`}).join('')}</section></div><div class="section-title" style="margin-top:28px"><h2>Результаты уроков</h2><span class="muted" style="font-size:11px">Освоено = не менее 75% в практике урока</span></div><div class="route">${trackUnits().filter(u=>state.units[u.id]).map(u=>`<button class="route-row" data-action="lesson" data-id="${u.id}"><span class="route-num">${String(u.id).padStart(2,'0')}</span><span class="route-text"><strong>${e(u.ru)}</strong><small>${state.units[u.id].attempts} ${plural(state.units[u.id].attempts,'попытка','попытки','попыток')}</small></span><strong style="font-size:13px">${state.units[u.id].best}%</strong>${icon('chevron')}</button>`).join('')||'<div class="search-empty">Заверши практику любого урока, чтобы увидеть результат.</div>'}</div><div class="notice">Результаты показывают выполнение упражнений выбранной ступени. Это не оценка уровня CEFR и не сертификат владения языком.</div>`}
function methodView(){return heading('Учиться так, чтобы помнить','Меньше зубрёжки. Больше понятного английского и осмысленной практики.')+`<p class="method-intro">English Step объединяет три последовательные ступени: 20 базовых уроков Grammarway 1, 20 разговорных тем English File Intermediate (Oxford University Press, 5-е изд.) и 69 модулей English for Everyone Advanced (DK). Порядок тем соответствует книгам, но объяснения, диалоги и задания написаны для этого приложения, без копирования страниц и аудио издательств. Уровни A1–A2, B1–B1+, B2–C1 — ориентиры, а не подтверждение сертификата.</p><div class="method-grid"><section class="card"><div class="iconbox">${icon('repeat')}</div><h3>Возвращаться с интервалами</h3><p>Метаанализ Kim и Webb (2022) обнаружил пользу распределённой практики для изучения второго языка. Поэтому задания возвращаются позже. Интервалы 1, 3, 7, 14 и 30 дней — практическая настройка этого сайта, а не универсальная научная формула.</p><a href="https://doi.org/10.1111/lang.12479" target="_blank" rel="noopener noreferrer">Исследование Kim & Webb ↗</a></section><section class="card"><div class="iconbox blue">${icon('bulb')}</div><h3>Доставать ответ из памяти</h3><p>В исследовании Karpicke и Roediger (2008) повторное припоминание иностранных слов улучшало отсроченное воспроизведение. Здесь ты не только выбираешь варианты: вводишь ответ, строишь фразу и пишешь диктант.</p><a href="https://profiles.wustl.edu/en/publications/the-critical-importance-of-retrieval-for-learning/" target="_blank" rel="noopener noreferrer">Исследование об активном припоминании ↗</a></section><section class="card"><div class="iconbox peach">${icon('book')}</div><h3>Замечать, как работает язык</h3><p>British Council предлагает связывать грамматическую форму со смыслом и замечать разницу между собственной фразой и образцом. Поэтому после ответа есть объяснение, а в уроках — сравнение русской и английской конструкции: «Я студент» → I am a student.</p><a href="https://www.britishcouncil.org/voices-magazine/ways-to-help-english-language-learners-notice-grammar" target="_blank" rel="noopener noreferrer">Практика noticing от British Council ↗</a></section><section class="card"><div class="iconbox">${icon('sound')}</div><h3>Слушать, читать и говорить</h3><p>Подход Пола Нейшена «четыре направления» соединяет понимание, собственную речь, изучение формы и развитие беглости. В каждом уроке есть диалог и задание о себе. Дополняй курс понятными короткими видео, чтением и разговором с человеком.</p><a href="https://www.tesolunion.org/archives-info/409" target="_blank" rel="noopener noreferrer">Paul Nation · Revisiting the Four Strands ↗</a></section></div><div class="notice"><strong>Как заниматься: 15 минут для начала.</strong><br>3 минуты — вспомнить старое. 4 минуты — понять правило. 5 минут — выполнить задания. 3 минуты — послушать диалог и сказать свои фразы. Продолжительность — ориентир; можно учиться в своём темпе.</div><section class="card"><h3>Что особенно полезно русскоязычному ученику</h3><p style="font-size:12px;color:var(--muted);margin-top:13px">Обращай внимание на am/is/are в настоящем времени, артикли a/an/the, do/does/did в вопросах, окончание -s после he/she/it и порядок слов. Переводи смысл целой фразы, а не каждое слово отдельно. В блоке «Русская привычка» показан конкретный пример и его исправление.</p><p style="font-size:12px;color:var(--muted);margin-top:12px">Для произношения: сначала послушай фразу, затем повтори, закрой образец и скажи ещё раз. Произнеси конечные согласные; сравни короткое /ɪ/ и долгое /iː/. Озвучка синтезируется браузером и зависит от установленных английских голосов. Сайт не оценивает произношение и свободный текст автоматически.</p></section>`}
function settingsView(){return heading('В твоём темпе','Учись с любого устройства — прогресс сохраняется в твоём аккаунте.')+`<div class="two-col"><section class="card settings-form"><form id="settingsForm"><label for="name">Как тебя называть</label><input id="name" name="name" value="${e(state.name)}" maxlength="30" required><label for="goal">Ежедневная цель</label><select name="goal" id="goal">${[5,10,15,20].map(n=>`<option value="${n}" ${n===state.goal?'selected':''}>${n} ответов в день</option>`).join('')}</select><label for="rate">Скорость английской озвучки</label><select name="rate" id="rate">${[[.65,'Медленно'],[.85,'Спокойно'],[1,'Обычно']].map(([v,t])=>`<option value="${v}" ${v===state.settings.rate?'selected':''}>${t}</option>`).join('')}</select><p>Голос выбирается из английских голосов, доступных в браузере. Для диктанта нужны звук и установленный английский голос.</p><button class="btn" type="submit">Сохранить настройки ${icon('check')}</button></form></section><div><section class="card settings-card"><h3>Один аккаунт — все устройства</h3><p>Прогресс автоматически сохраняется на сервере. На телефоне и компьютере открывай этот же сайт и входи в один и тот же аккаунт English Step.</p><div style="margin-top:14px">${cloudBadge()}</div><p id="cloudDetail" style="margin-top:12px">${e(cloud.user?.email||'Подключаем аккаунт…')}</p><div class="settings-actions"><button class="btn white" data-action="sync-now">${icon('repeat')} Синхронизировать</button><a class="btn white" href="/login" target="_top">Войти в аккаунт</a><form method="post" action="/auth/logout"><button class="btn white" type="submit">Выйти</button></form></div><p style="margin-top:15px">При потере связи изменения остаются на устройстве и отправляются после восстановления соединения. Перед переходом на другое устройство дождись отметки «Сохранено в аккаунте».</p><h3 style="margin-top:22px">Резервная копия</h3><p>Можно дополнительно скачать прогресс в файл.</p><div class="settings-actions"><button class="btn white" data-action="export">${icon('download')} Экспорт</button><button class="btn white" data-action="import">${icon('upload')} Импорт</button><input type="file" id="importFile" accept="application/json,.json"></div><p style="margin-top:13px;font-size:10px">Импорт заменяет прогресс в аккаунте на всех устройствах. Перед заменой сайт предложит подтверждение.</p></section><section class="card settings-card" style="margin-top:20px"><h3>Начать заново</h3><p>Удалить результаты уроков, избранные слова и расписание повторений из аккаунта на всех устройствах.</p><button class="btn danger" style="margin-top:17px" data-action="reset">Сбросить прогресс</button></section>${cloud.read('english-step-conflict-backup')?'<button class="btn white" style="margin-top:15px" data-action="export-backup">Скачать локальную копию до замены</button>':''}<p class="speech-note">Для страницы методики на телефоне: <a href="#method">Как учиться и источники ↗</a></p></div></div>`}
function openModal(){if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden'}
function closeModal(){dialog.close();document.body.style.overflow='';if('speechSynthesis'in window)window.speechSynthesis.cancel();session=null;lesson=null;shell()}
function modalHeader(title,kicker){return `<header class="modal-top"><div><div class="eyebrow">${e(kicker)}</div><h2>${e(title)}</h2></div><button class="icon-btn" data-action="close" aria-label="Закрыть урок">${icon('close')}</button></header>`}
function openLesson(id,tab='learn'){lesson=units.find(u=>u.id===Number(id));if(!lesson)return;session=null;lessonTab=tab;showTranslation=true;renderLesson();openModal()}
function renderLesson(){content.innerHTML=modalHeader(lesson.ru,`${e(lesson.unitNo||`УРОК ${String(lesson.id).padStart(2,'0')}`)} · ${e(trackInfo(lesson.track||'grammarway').name)} · СТР. ${lesson.bookPage}`)+`<div class="modal-body"><div class="lesson-tabs" role="tablist" aria-label="Части урока">${[['learn','1. Разобраться'],['practice','2. Попробовать'],['speak','3. Применить']].map(([id,t])=>`<button role="tab" aria-selected="${lessonTab===id}" class="${lessonTab===id?'active':''}" data-action="lesson-tab" data-tab="${id}">${t}</button>`).join('')}</div>${lessonTab==='learn'?learnContent():speakingContent()}</div>`;dialog.scrollTop=0}
function mediaExamples(){
 const examples=mediaLessons.find(x=>x.unitId===lesson.id)?.examples||[];
 if(!examples.length)return '';
 return `<section class="media-examples" aria-labelledby="mediaLessonTitle"><div class="section-title"><h3 id="mediaLessonTitle">Правило в знакомой истории</h3><span class="pill">Кино + комиксы</span></div><p class="media-disclaimer">Учебные мини-сцены по мотивам. Фразы написаны для курса и не являются дословными цитатами из фильмов или комиксов.</p><div class="media-example-grid">${examples.map((x,i)=>`<article class="media-example ${x.kind}"><div class="media-kicker">${icon(x.kind==='film'?'film':'book')} ${x.kind==='film'?'КИНО':'КОМИКСЫ'}</div><h4>${e(x.title)}</h4><p class="media-context">${e(x.context)}</p><div class="media-line"><p lang="en">${x.en.split(x.focus).map(e).join(`<mark>${e(x.focus)}</mark>`)}</p><button class="icon-btn" data-action="speak-media" data-id="${i}" aria-label="Озвучить учебный пример ${i+1}">${icon('sound')}</button></div><p class="media-translation">${e(x.ru)}</p><p class="media-why">${e(x.why)}</p><div class="media-check"><strong>Твой ход</strong><p>${e(x.prompt)}</p><details><summary>Показать ответ и разбор</summary><p lang="en" class="media-answer">${e(x.answer)}</p><p>${e(x.answerWhy)}</p></details></div><a class="media-source" href="${e(x.source.url)}" target="_blank" rel="noopener noreferrer">${e(x.source.label)} ↗</a></article>`).join('')}</div><p class="media-note">Сначала ответь вслух, потом открой разбор. Эти мини-задания не влияют на XP. Озвучка — голос браузера.</p><button class="text-btn" data-action="media-catalog">Подобрать фильм для своего уровня ${icon('arrow')}</button></section>`;
}
function filmsView(){
 return heading('Английский, который хочется смотреть','24 культовых фильма и любимых истории. От первых реплик до тонкого подтекста.')+`<section class="cinema-hero"><div><div class="eyebrow">ТВОЙ НЕБОЛЬШОЙ КИНОКЛУБ</div><h2>Знакомая история.<br>Новый способ услышать её.</h2><p>Выбирай интересный фильм, разбирай одну сцену и забирай из неё пару фраз в свою речь.</p><button class="btn lime" data-action="film-filter" data-filter="A1" data-scroll="true">Начать с первых реплик ${icon('arrow')}</button></div><div class="cinema-stamp" aria-hidden="true"><span>ENGLISH<br>IN SCENES</span><strong>A1 → C2</strong><small>WATCH · NOTICE · SAY</small></div></section><aside class="cinema-guidance"><strong>Уровень — ориентир для задания, а не оценка всего фильма.</strong><p>Это приблизительная авторская подборка, а не официальная классификация CEFR. Сложность зависит от сцены, знакомого сюжета и субтитров. На A1 работаем с 30–90 секундами; на A2 — с короткими знакомыми эпизодами. Понимать фильм целиком пока не требуется.</p></aside><ol class="cinema-steps"><li><b>01</b><div><strong>Поймай смысл</strong><p>Посмотри небольшой фрагмент. Если трудно, включи английские субтитры и проверь перевод ключевых слов.</p></div></li><li><b>02</b><div><strong>Услышь ещё раз</strong><p>Выбери 2–3 полезные реплики. Пересмотри, сделай паузу и повтори вслух с похожей интонацией.</p></div></li><li><b>03</b><div><strong>Скажи по-своему</strong><p>Закрой текст. Перескажи момент или составь собственные фразы по заданию из карточки.</p></div></li></ol><div class="filterbar film-filters" aria-label="Фильтр фильмов по уровню"><button class="filter ${filter==='all'?'active':''}" data-action="film-filter" data-filter="all" aria-pressed="${filter==='all'}">Все уровни</button>${filmCatalog.levels.map(l=>`<button class="filter ${filter===l.id?'active':''}" data-action="film-filter" data-filter="${l.id}" aria-pressed="${filter===l.id}">${l.id}</button>`).join('')}<input type="search" class="search" id="filmSearch" value="${e(query)}" placeholder="Название или жанр…" aria-label="Поиск фильма по названию или жанру"></div><div id="filmResults">${filmResults()}</div><details class="cinema-sources"><summary>Как составлена подборка и источники</summary><p>Учебные уровни, задания и рекомендации по просмотру — авторская оценка. Факты о фильмах сверены со страницами студий и BFI; источник указан в каждой карточке. Ссылки ведут к информации о произведениях, а не к просмотру фильма.</p><ul><li><a target="_blank" rel="noopener noreferrer" href="https://learnenglishteens.britishcouncil.org/exams/listening-exams/listen-listen-listen">British Council: аудирование и английские субтитры ↗</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://www.britishcouncil.org/voices-magazine/how-to-use-tv-series-trailers-films-language-class">British Council: работа с короткими сценами ↗</a></li>${filmCatalog.sources.map(s=>`<li><a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.label)} ↗</a></li>`).join('')}</ul></details>`;
}
function filmResults(){
 const matches=filmCatalog.films.filter(f=>(filter==='all'||f.level===filter)&&`${f.title} ${f.ru} ${f.genre}`.toLowerCase().includes(query.trim().toLowerCase()));
 if(!matches.length)return '<div class="empty"><h2>Такой фильм пока не нашёлся</h2><p>Попробуй другое название, жанр или выбери все уровни.</p></div>';
 return `<p class="film-count" role="status">В подборке: ${matches.length} ${plural(matches.length,'фильм','фильма','фильмов')}</p>`+filmCatalog.levels.map(l=>{const films=matches.filter(f=>f.level===l.id);if(!films.length)return '';return `<section class="film-level" id="films-${l.id}"><div class="film-level-head"><span class="level-badge">${l.id}</span><div><h2>${e(l.title)}</h2><p>${e(l.description)}</p></div></div><p class="film-mode">${icon('play')}<span>${e(l.mode)}</span></p><div class="film-grid">${films.map((f,i)=>`<article class="film-card"><div class="film-card-top"><span>${e(f.genre)}</span><span>${f.year}</span></div><div class="film-title"><span class="film-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><div><h3 lang="en">${e(f.title)}</h3><p>${e(f.ru)}</p></div></div><p class="film-accent">${e(f.accent)}</p><p class="film-why">${e(f.why)}</p><div class="film-watch"><strong>Как смотреть</strong><p>${e(f.watch)}</p></div><details class="film-assignment"><summary>Задание и сложные места</summary><p><strong>Обрати внимание</strong>${e(f.challenge)}</p><p><strong>Твой мини-разбор</strong>${e(f.task)}</p><div class="film-related"><span>Повтори перед просмотром:</span>${f.units.map(id=>`<button class="film-unit" data-action="lesson" data-id="${id}">Тема ${id} · ${e(units.find(u=>u.id===id).ru)}</button>`).join('')}</div></details><a class="media-source" href="${e(f.source.url)}" target="_blank" rel="noopener noreferrer">${e(f.source.label)} ↗</a></article>`).join('')}</div></section>`}).join('');
}

function learnContent(){return `<p class="lesson-intro">${e(lesson.summary)}</p>${lesson.rules.map((r,i)=>`<section class="rule"><h3>${i+1}. ${e(r.title)}</h3><p>${e(r.body)}</p><div class="example"><span>${e(r.example)}<small>${e(r.translation)}</small></span><button class="icon-btn" data-action="speak-example" data-id="${i}" aria-label="Послушать пример ${i+1}">${icon('sound')}</button></div></section>`).join('')}<aside class="trap"><strong>${(lesson.track||'grammarway')==='grammarway'?'Русская привычка → английская фраза':'Проверь себя · типичная ошибка'}</strong><p><span class="wrong">${e(lesson.trap.wrong)}</span><span>${e(lesson.trap.right)}</span></p><small>${e(lesson.trap.why)}</small></aside>${lesson.reading?`<section class="lesson-reading"><div class="eyebrow">READING · ЧТЕНИЕ В КОНТЕКСТЕ</div><h3>${e(lesson.reading.title)}</h3><p lang="en">${e(lesson.reading.text)}</p><small>Прочитай без словаря, найди главную мысль, затем ответь на вопрос в практике.</small></section>`:''}${mediaExamples()}${lesson.pronunciation?`<section class="lesson-pronounce"><strong>Произношение · говори вслух</strong><p>${e(lesson.pronunciation)}</p><small>Озвучка генерируется браузером. Оригинальное аудио учебников не включено.</small></section>`:''}<div class="lesson-actions"><small>Пора проверить правило на практике.</small><button class="btn" data-action="practice-lesson">К упражнениям ${icon('arrow')}</button></div>`}
function speakingContent(){return `<div class="section-title"><span class="muted" style="font-size:12px">Послушай, повтори, поменяй детали.</span><button class="text-btn" data-action="toggle-translation">${showTranslation?'Скрыть':'Показать'} перевод</button></div><div class="dialogue">${lesson.dialogue.map((line,i)=>`<div class="speech-line"><div class="avatar">${e(line.who[0])}</div><div class="bubble"><strong>${e(line.who)}</strong><p>${e(line.en)}</p>${showTranslation&&line.ru?`<small>${e(line.ru)}</small>`:''}</div><button class="icon-btn" data-action="speak-line" data-id="${i}" aria-label="Послушать реплику ${i+1}">${icon('sound')}</button></div>`).join('')}</div><div class="speaking-task"><h3>Теперь — о тебе</h3><p>${e(lesson.speaking)}</p><textarea id="speakingNote" maxlength="5000" aria-label="Твои фразы на английском" placeholder="Напиши свои фразы. Затем произнеси их вслух…">${e(state.notes[lesson.id]||'')}</textarea><button class="btn" data-action="save-spoken">${icon('check')} ${state.spoken[lesson.id]?'Сохранить ещё раз':'Я произнёс вслух · сохранить'}</button><p class="speech-note">Это самостоятельная практика: текст сохраняется, но грамматика и произношение автоматически не оцениваются.</p></div><div class="lesson-actions"><button class="btn white" data-action="close">К моему курсу</button><button class="btn" data-action="next-lesson">${trackUnits(lesson.track||'grammarway').at(-1).id===lesson.id?'К повторению':'Следующий урок'} ${icon('arrow')}</button></div>`}
function startSession(kind,questions,unitId=null){if(!questions.length){toast('Пока нет подходящих заданий. Начни с урока.');return}session={kind,questions:questions.map(q=>({...q,options:q.options?shuffle(q.options):undefined,words:q.words?shuffle(q.words):undefined})),unitId,index:0,results:[],checked:false,value:'',selected:[],assisted:false,finished:false};renderExercise();openModal()}
function sessionTitle(){return {lesson:units.find(u=>u.id===session.unitId)?.ru,review:'Повторение по памяти',errors:'Работа над ошибками',daily:'Тренировка дня',revision:'Смешанная проверка',diagnostic:'С чего начнём?',vocab:'Вспомни слово'}[session.kind]}
function renderExercise(){const q=session.questions[session.index];const typeNames={choice:'Выбери ответ',input:'Вспомни и напиши',order:'Собери предложение',listen:'Поймай фразу на слух'};content.innerHTML=modalHeader(sessionTitle(),'ПРАКТИКА · МАЛЕНЬКИЕ ШАГИ')+`<div class="modal-body"><div class="exercise-info"><span>Задание ${session.index+1} из ${session.questions.length}</span><span>${e(q.unitTitle||'Слова в контексте')}</span></div><div class="progress"><i style="width:${session.index/session.questions.length*100}%"></i></div><div class="exercise-type">${typeNames[q.type]}</div><h3 class="exercise-prompt">${e(q.prompt)}</h3>${q.type==='choice'?`<div class="choices">${q.options.map((v,i)=>`<button class="choice" data-action="choose" data-id="${i}" aria-pressed="false"><span class="key">${i+1}</span><span>${e(v)}</span></button>`).join('')}</div>`:q.type==='order'?`<div class="tokens selected-tokens" id="selectedTokens" aria-label="Твоё предложение"><span class="hint">Нажимай на слова, чтобы собрать фразу</span></div><div class="tokens" id="availableTokens">${tokensHTML(q)}</div>`:`${q.type==='listen'?`<div class="listen-block"><button class="btn white" data-action="play-question">${icon('sound')} Послушать</button><button class="text-btn" data-action="play-slow">Медленнее</button></div><button class="fallback" data-action="audio-fallback">Нет звука? Показать текст (с подсказкой)</button><div id="audioFallback"></div>`:''}<input id="answerInput" class="answer-input" type="text" autocomplete="off" autocapitalize="off" spellcheck="false" aria-label="Твой ответ на английском" placeholder="Твой ответ на английском…">`}<div id="formError" class="form-error" role="alert"></div><div id="answerFeedback" aria-live="polite"></div><div class="lesson-actions"><small>${session.kind==='diagnostic'?'Это ориентир по темам, не экзамен на уровень.':q.type==='order'?'Нажми на выбранное слово, чтобы вернуть его.':'Сначала ответь сам. Затем разберём почему.'}</small><button class="btn" id="checkButton" data-action="check">Проверить ${icon('arrow')}</button></div><button class="text-btn" style="margin-top:18px;color:#95a18a" data-action="dont-know">Пока не знаю</button></div>`;dialog.scrollTop=0;content.querySelector('#answerInput')?.focus()}
function tokensHTML(q){return q.words.map((w,i)=>`<button class="token" data-action="token" data-id="${i}" ${session.selected.includes(i)?'disabled':''}>${e(w)}</button>`).join('')}
function checkAnswer(dontKnow=false){if(!session||session.checked)return;const q=session.questions[session.index];let value=q.type==='choice'?session.value:q.type==='order'?session.selected.map(i=>q.words[i]).join(' '):content.querySelector('#answerInput')?.value||'';if(!value.trim()&&!dontKnow){content.querySelector('#formError').textContent='Сначала напиши или выбери ответ.';return}session.checked=true;const matched=!dontKnow&&correctAnswer(q,value),ok=matched&&!session.assisted;session.results.push({q,ok,value,assisted:session.assisted});recordAnswer(q,matched,session.assisted);content.querySelectorAll('.choice,.token,#answerInput,[data-action="dont-know"],[data-action="audio-fallback"]').forEach(el=>el.disabled=true);if(q.type==='choice')content.querySelectorAll('.choice').forEach((el,i)=>{if(correctAnswer(q,q.options[i]))el.classList.add('correct');else if(q.options[i]===session.value)el.classList.add('incorrect')});content.querySelector('#formError').textContent='';content.querySelector('#answerFeedback').innerHTML=`<div class="feedback ${ok?'':'wrong'}"><strong>${ok?'Верно. Ещё один шаг!':session.assisted&&matched?'Получилось с подсказкой':'Разберём вместе'}</strong>${!ok?`<span class="answer">${e((q.answers||[q.answer])[0])}</span>`:''}${e(q.explanation)}${session.assisted?'<p style="margin-top:8px">Ответ с открытым текстом не засчитывается как самостоятельный.</p>':''}</div>`;const b=content.querySelector('#checkButton');b.dataset.action='next-question';b.innerHTML=`${session.index+1===session.questions.length?'Мой результат':'Дальше'} ${icon('arrow')}`;b.focus()}
function nextQuestion(){if(!session?.checked)return;if(session.index+1>=session.questions.length){finishSession();return}session.index++;session.checked=false;session.value='';session.selected=[];session.assisted=false;renderExercise()}
function finishSession(){if(!session||session.finished)return;session.finished=true;const correct=session.results.filter(x=>x.ok).length,total=session.questions.length,pct=Math.round(correct/total*100);if(session.kind==='lesson'){const prev=state.units[session.unitId]||{best:0,attempts:0,completed:false};state.units[session.unitId]={best:Math.max(prev.best,pct),attempts:prev.attempts+1,completed:prev.completed||pct>=75,last:Date.now()};state.days[today()].lessons++;state.recommended=Math.min(trackUnits(units.find(u=>u.id===session.unitId)?.track||'grammarway').at(-1).id,session.unitId+(pct>=75?1:0))}let recommended=null;if(session.kind==='diagnostic'){const fail=session.results.find(x=>!x.ok);recommended=fail?.q.unitId||trackUnits().at(-1).id;state.recommended=recommended}save();const wrong=session.results.filter(x=>!x.ok).length;content.innerHTML=modalHeader('Маленькая победа','ПРАКТИКА ЗАВЕРШЕНА')+`<div class="modal-body"><section class="result"><div class="result-icon">${icon(pct>=75?'leaf':'bulb')}</div><h2>${session.kind==='diagnostic'?'Твоя точка старта':pct>=75?'Отличная работа!':'Всё начинается с практики'}</h2><p>${session.kind==='diagnostic'?`Предлагаем начать с темы «${e(units.find(u=>u.id===recommended).ru)}». Любой урок остаётся доступен.`:pct>=75?'Ты вспомнил, попробовал и стал увереннее. Теперь примени это в своих фразах.':'Посмотри объяснения и вернись к трудным заданиям. Ошибки помогают понять, что повторить.'}</p><div class="result-score">${correct}<span style="font-size:24px;color:#a0ae91"> / ${total}</span></div><div class="result-stats"><span>${pct}% самостоятельно</span><span>+${correct*10+(total-correct)*2} XP</span><span>${wrong?`${wrong} стоит повторить`:'Все ответы верные'}</span></div>${session.kind==='lesson'?`<p>${pct>=75?'Урок отмечен как освоенный.':'Для отметки «Освоено» нужно не менее 75%.'} Повторения уже запланированы.</p>`:''}<div class="result-buttons">${session.kind==='diagnostic'?`<button class="btn" data-action="lesson" data-id="${recommended}">Начать с этой темы ${icon('arrow')}</button>`:session.kind==='lesson'?`<button class="btn" data-action="speak-unit" data-id="${session.unitId}">Применить в диалоге ${icon('arrow')}</button>`:''}${wrong?'<button class="btn white" data-action="retry-session">Повторить ошибки</button>':''}<button class="btn ${session.kind==='lesson'||session.kind==='diagnostic'?'white':''}" data-action="close">Готово ${icon('check')}</button></div></section></div>`;dialog.scrollTop=0}
function speak(text,rate=state.settings.rate){if(!('speechSynthesis'in window)){toast('В этом браузере озвучка недоступна. Открой сайт в Chrome или Safari.');return}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=rate;const vs=window.speechSynthesis.getVoices();const v=vs.find(v=>v.lang==='en-GB')||vs.find(v=>v.lang.startsWith('en'));if(v)u.voice=v;u.onerror=ev=>{if(ev.error!=='interrupted'&&ev.error!=='canceled')toast('Не удалось воспроизвести голос. Проверь звук и английские голоса браузера.')};window.speechSynthesis.speak(u)}
function startDaily(){const candidates=[...dueQuestions(),...allQuestions.filter(q=>q.unitId===nextUnit().id),...shuffle(allQuestions.filter(q=>state.units[q.unitId]?.completed))];const unique=[...new Map(candidates.map(q=>[q.key,q])).values()];startSession('daily',unique.slice(0,state.goal))}
function startDiagnostic(){const list=trackUnits();const step=Math.max(1,Math.floor(list.length/10));const selected=activeTrack()==='grammarway'?[1,2,3,4,6,9,11,12,13,15,17,19].map(id=>units.find(u=>u.id===id)):list.filter((_,i)=>i%step===0).slice(0,12);startSession('diagnostic',selected.map(u=>u.exercises.find(q=>q.type==='input')||u.exercises[0]))}
function practiceWords(){const list=shuffle(filteredWords()).slice(0,10);if(!list.length){toast('Добавь слова или измени фильтр.');return}startSession('vocab',list.map(w=>({key:w.key,type:'input',unitId:w.unitId,unitTitle:'Урок '+w.unitId,prompt:`Как по-английски «${w.ru}»?`,answers:[w.en],explanation:`${w.en} — ${w.ru}. В контексте: ${w.example}`})))}
function exportProgress(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`english-step-progress-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Файл прогресса готов к сохранению.')}
async function importProgress(file){if(!file)return;if(file.size>2e6){toast('Файл слишком большой. Выбери экспорт прогресса English Step.');return}try{const clean=validateState(JSON.parse(await file.text()));if(!confirm('Заменить прогресс в аккаунте на всех устройствах данными из файла?'))return;await cloud.replace(clean);storageOK=true;shell();toast('Прогресс восстановлен и сохранён в аккаунте.')}catch(err){toast('Не удалось импортировать файл: '+err.message)}}
function navigate(r){location.hash=r;if(route===r)shell()}
function handleAction(action,id,el){switch(action){
 case'reload':location.reload();break;
 case'navigate':navigate(el.dataset.route);break;
 case'lesson':openLesson(Number(id));break;
 case'speak-unit':openLesson(Number(id),'speak');break;
 case'close':closeModal();break;
 case'lesson-tab':if(el.dataset.tab==='practice')startSession('lesson',lesson.exercises,lesson.id);else{lessonTab=el.dataset.tab;renderLesson()}break;
 case'practice-lesson':startSession('lesson',lesson.exercises,lesson.id);break;
 case'next-lesson':{const ls=trackUnits(lesson.track||'grammarway');const n=ls.findIndex(u=>u.id===lesson.id);if(n===ls.length-1){closeModal();navigate('review')}else openLesson(ls[n+1].id);break}
 case'track':state.settings.track=tracks.some(t=>t.id===id)?id:'grammarway';filter='all';query='';save();shell();break;
 case'track-go':state.settings.track=tracks.some(t=>t.id===id)?id:'grammarway';filter='all';query='';save();navigate('course');break;
 case'track-revision':{const selected=trackUnits().filter(u=>u.chapter===Number(id));const qs=shuffle(selected.flatMap(u=>u.exercises)).slice(0,Math.min(15,selected.length*5));startSession('revision',qs);break}
 case'course-filter':filter=el.dataset.filter;renderPage();break;
 case'film-filter':{filter=el.dataset.filter;renderPage();document.querySelector(`[data-action="film-filter"][data-filter="${filter}"]`)?.focus({preventScroll:true});if(el.dataset.scroll==='true')document.getElementById('filmResults')?.scrollIntoView({block:'start',behavior:'smooth'});break}
 case'media-catalog':closeModal();navigate('films');break;
 case'speak-media':{const x=mediaLessons.find(x=>x.unitId===lesson?.id)?.examples[Number(id)];if(x)speak(x.en);break}
 case'word-filter':filter=el.dataset.filter;renderPage();break;
 case'star':state.stars=state.stars.includes(id)?state.stars.filter(x=>x!==id):[...state.stars,id];save();renderPage();break;
 case'speak-word':speak(words.find(w=>w.key===id).en);break;
 case'phrase':speak('One step at a time.');break;
 case'speak-example':speak(lesson.rules[Number(id)].example);break;
 case'speak-line':speak(lesson.dialogue[Number(id)].en);break;
 case'toggle-translation':showTranslation=!showTranslation;state.notes[lesson.id]=content.querySelector('#speakingNote').value;save();renderLesson();break;
 case'save-spoken':{state.notes[lesson.id]=content.querySelector('#speakingNote').value;state.spoken[lesson.id]=true;const d=state.days[today()]||{answers:0,correct:0,lessons:0,spoken:0};d.spoken++;state.days[today()]=d;save();toast('Фразы сохранены. Хорошая практика!');break}
 case'choose':if(!session.checked){session.value=session.questions[session.index].options[Number(id)];content.querySelectorAll('.choice').forEach((b,i)=>{b.classList.toggle('selected',i===Number(id));b.setAttribute('aria-pressed',String(i===Number(id)))});content.querySelector('#formError').textContent=''}break;
 case'token':if(!session.checked){session.selected.push(Number(id));updateTokens()}break;
 case'un-token':if(!session.checked){session.selected.splice(Number(id),1);updateTokens()}break;
 case'check':checkAnswer();break;
 case'dont-know':checkAnswer(true);break;
 case'next-question':nextQuestion();break;
 case'play-question':speak(session.questions[session.index].audio);break;
 case'play-slow':speak(session.questions[session.index].audio,.65);break;
 case'audio-fallback':session.assisted=true;content.querySelector('#audioFallback').innerHTML=`<div class="readback">${e(session.questions[session.index].audio)}<small style="display:block;margin-top:5px">Ответ будет отмечен как выполненный с подсказкой.</small></div>`;break;
 case'retry-session':{const qs=session.results.filter(r=>!r.ok).map(r=>r.q);const kind=session.kind==='vocab'?'vocab':'errors';startSession(kind,qs);break}
 case'review-due':startSession('review',dueQuestions().slice(0,20));break;
 case'review-errors':startSession('errors',errorQuestions().slice(0,20));break;
 case'daily':startDaily();break;
 case'revision':{const bound=Number(id)*5,qs=shuffle(allQuestions.filter(q=>q.unitId<=bound)).slice(0,Math.min(15,bound*2));startSession('revision',qs);break}
 case'diagnostic':startDiagnostic();break;
 case'word-practice':practiceWords();break;
 case'export':exportProgress();break;
 case'import':document.getElementById('importFile').click();break;
 case'reset':if(confirm('Удалить весь прогресс English Step из аккаунта на всех устройствах? Сначала можно экспортировать его.')){const clean=defaultState();clean.name=state.name;cloud.replace(clean).then(()=>{shell();toast('Прогресс сброшен в аккаунте.')}).catch(err=>toast(err.message))}break;
 case'sync-now':cloud.sync().then(ok=>toast(ok?'Прогресс синхронизирован.':'Пока нет подтверждения сервера. Проверь соединение и вход в аккаунт.'));break;
 case'export-backup':{const raw=cloud.read('english-step-conflict-backup');if(raw){const url=URL.createObjectURL(new Blob([raw],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='english-step-local-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}break}
}}
function updateTokens(){const q=session.questions[session.index];content.querySelector('#selectedTokens').innerHTML=session.selected.map((i,j)=>`<button class="token" data-action="un-token" data-id="${j}">${e(q.words[i])}</button>`).join('')||'<span class="hint">Нажимай на слова, чтобы собрать фразу</span>';content.querySelector('#availableTokens').innerHTML=tokensHTML(q);content.querySelector('#formError').textContent=''}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(el&&!el.disabled)handleAction(el.dataset.action,el.dataset.id,el)});
document.addEventListener('input',ev=>{if(ev.target.id==='courseSearch'){query=ev.target.value;document.getElementById('courseResults').innerHTML=courseResults()}if(ev.target.id==='filmSearch'){query=ev.target.value;document.getElementById('filmResults').innerHTML=filmResults()}if(ev.target.id==='wordSearch'){query=ev.target.value;document.getElementById('wordResults').innerHTML=wordResults()}if(ev.target.id==='speakingNote'&&lesson){state.notes[lesson.id]=ev.target.value;save()}});
document.addEventListener('change',ev=>{if(ev.target.id==='importFile')importProgress(ev.target.files[0])});
document.addEventListener('submit',ev=>{if(ev.target.id==='settingsForm'){ev.preventDefault();const f=new FormData(ev.target);const name=f.get('name').trim();if(!name){toast('Напиши имя или ник.');return}state.name=name.slice(0,30);state.goal=Number(f.get('goal'));state.settings.rate=Number(f.get('rate'));save();shell();toast('Настройки сохранены.')}});
document.addEventListener('keydown',ev=>{if(dialog.open&&session&&!session.finished&&ev.key==='Enter'&&ev.target.tagName==='INPUT'){ev.preventDefault();session.checked?nextQuestion():checkAnswer()}});
dialog.addEventListener('cancel',ev=>{ev.preventDefault();closeModal()});
window.addEventListener('hashchange',()=>{route=Object.hasOwn(routeTitles,location.hash.slice(1))?location.hash.slice(1):'home';filter='all';query='';shell();window.scrollTo(0,0)});
async function init(){try{const data=await Promise.all(['units-1.json','units-2.json','units-english-file.json','units-dk-advanced.json','media-lessons.json','film-selection.json'].map(async p=>{const res=await fetch(p);if(!res.ok)throw new Error('Не удалось загрузить уроки');return res.json()}));units=[...data[0],...data[1],...data[2],...data[3]].map(u=>({...u,track:u.track||'grammarway',chapter:u.chapter||Math.ceil(u.id/5)})).sort((a,b)=>a.id-b.id);mediaLessons=data[4];filmCatalog=data[5];if(units.length!==109)throw new Error('Не все уроки загружены');for(const u of units){u.exercises=u.exercises.map((q,i)=>({...q,key:`u${u.id}-q${i}`,unitId:u.id,unitTitle:u.ru}));words.push(...u.vocab.map((w,i)=>({...w,key:`u${u.id}-v${i}`,unitId:u.id})))}allQuestions=units.flatMap(u=>u.exercises);await cloud.initialize();route=Object.hasOwn(routeTitles,location.hash.slice(1))?location.hash.slice(1):'home';shell();cloud.sync();setInterval(()=>{if(document.visibilityState!=='hidden')cloud.sync()},20000)}catch(err){app.innerHTML=`<div class="loading">Не удалось открыть курс<span>${e(err.message)}. Проверь соединение и обнови страницу.</span><button class="btn" style="margin-top:20px" data-action="reload">Попробовать снова</button></div>`}}
window.addEventListener('online',()=>cloud.sync());
window.addEventListener('focus',()=>cloud.sync());
document.addEventListener('visibilitychange',()=>cloud.sync());
window.addEventListener('pagehide',()=>{cloud.persist();cloud.sync()});
init();
